import { Legend as RechartsLegend } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { LegendProps, LegendEntry } from "../chart.types";
import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

import LegendContent from "./legend-content";

const Legend = (props: LegendProps) => {
  const theme = useTheme();
  const { type, chartData, numCategoricalColors, colorMap: contextColorMap } = useChart();
  const colorMap = props.colorMap || contextColorMap;
  // Destructure layout so it is never forwarded directly to RechartsLegend.
  // "dashboard" is a Textura-only extension; Recharts only accepts "horizontal" | "vertical".
  const {
    layout: layoutProp = "horizontal",
    align = "left",
    verticalAlign = "bottom",
    ...rechartsProps
  } = props;
  const layout = layoutProp;
  // "dashboard" is a Textura-only layout extension. Recharts only accepts "horizontal" | "vertical".
  // Passing "horizontal" explicitly causes Recharts to allocate internal bottom space for the legend,
  // which conflicts with the bottom margin we already set in AreaChart/BarChart. Omitting the prop
  // entirely lets Recharts use its default behaviour, which is what the original code relied on.
  const rechartsLayout = layoutProp === "dashboard" ? undefined : layoutProp;

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const content = (contentProps: any) => {
    let payload = props.payload || contentProps?.payload;
    if (type === "categorical") {
      payload = chartData?.map((_entry, index) => {
        const colorIndex = index % numCategoricalColors;
        const colorKey = `${colorIndex + 1}Default` as keyof typeof theme.color.data.categorical;
        const color = theme.color.data.categorical[colorKey];
        return {
          value: (_entry as { name: string }).name,
          color,
        };
      });
    }

    // If payload is provided manually, try to resolve missing colors from chart context (AreaChart)
    const enrichedPayload = payload?.map((entry: LegendEntry) => {
      if (entry.color || entry.fill || entry.stroke) return entry;

      const resolvedColor = colorMap?.[String(entry.value)];
      if (resolvedColor) {
        return { ...entry, color: resolvedColor };
      }
      return entry;
    });

    return <LegendContent {...props} {...contentProps} layout={layout} payload={enrichedPayload} />;
  };

  return (
    <RechartsLegend
      {...rechartsProps}
      align={align}
      className={clsx(
        ChartClasses.legendWrapper,
        layout === "dashboard" && ChartClasses.legendDashboard,
        rechartsProps.className,
      )}
      content={content}
      layout={rechartsLayout}
      verticalAlign={verticalAlign}
      wrapperStyle={{
        width: layout === "dashboard" ? "unset" : align === "center" ? "100%" : "fit-content",
        left: align === "left" || layout === "dashboard" ? 10 : undefined,
        right: align === "right" || layout === "dashboard" ? 10 : undefined,
        bottom: verticalAlign === "bottom" ? 0 : undefined,
        ...rechartsProps.wrapperStyle,
      }}
    />
  );
};

Legend.displayName = "Legend";

export default Legend;
